// components/ui/modal.tsx — Holy Trinity Dialog & Animated Modal Primitive
// Fully compliant with WAI-ARIA Dialog (Modal) pattern via Radix UI:
// - Portaled rendering to document.body via Dialog.Portal
// - Accessible title (aria-labelledby) and optional description (aria-describedby)
// - Accessible focus trap, initial focus, focus restoration on close, Escape dismiss
// - Strict body scroll lock
// - Fixed-height container with scrollable long-content region (min-h-0 flex-1 overflow-y-auto)
// - Header and footer remain pinned (shrink-0) and reachable on narrow devices
// - Sensible near-full-screen mobile behavior with safe-area padding
// - 44px mobile touch targets on close button and interactive triggers
// - Motion reduction support (prefers-reduced-motion)

"use client";

import React, { useEffect } from "react";
import * as Dialog from "@radix-ui/react-dialog";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { X } from "lucide-react";
import { OVERLAY_LAYERS } from "../navigation/overlay-layers";

export interface AnimatedModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: React.ReactNode;
  description?: React.ReactNode;
  children: React.ReactNode;
  maxWidth?: string;
  className?: string;
  trigger?: React.ReactNode;
  position?: "center" | "right";
  footer?: React.ReactNode;
  bodyClassName?: string;
  headerClassName?: string;
  footerClassName?: string;
}

export function AnimatedModal({
  isOpen,
  onClose,
  title,
  description,
  children,
  maxWidth = "max-w-lg",
  className = "",
  trigger,
  position = "center",
  footer,
  bodyClassName = "",
  headerClassName = "",
  footerClassName = "",
}: AnimatedModalProps) {
  const isRightDrawer = position === "right";
  const shouldReduceMotion = useReducedMotion();

  // Strict body scroll lock when open
  useEffect(() => {
    if (!isOpen) return;
    const originalOverflow = document.body.style.overflow;
    const originalTouchAction = document.body.style.touchAction;
    document.body.style.overflow = "hidden";
    document.body.style.touchAction = "none";

    return () => {
      document.body.style.overflow = originalOverflow;
      document.body.style.touchAction = originalTouchAction;
    };
  }, [isOpen]);

  const modalSpringTransition = shouldReduceMotion
    ? { duration: 0 }
    : {
        type: "spring" as const,
        damping: 28,
        stiffness: 320,
        mass: 0.8,
      };

  return (
    <Dialog.Root
      open={isOpen}
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      {trigger && <Dialog.Trigger asChild>{trigger}</Dialog.Trigger>}
      <AnimatePresence>
        {isOpen && (
          <Dialog.Portal forceMount>
            <Dialog.Overlay asChild>
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.18, ease: "easeOut" }}
                className={`fixed inset-0 ${OVERLAY_LAYERS.MODAL} bg-black/80 backdrop-blur-sm`}
              />
            </Dialog.Overlay>

            <div
              data-lenis-prevent
              className={`fixed inset-0 ${OVERLAY_LAYERS.MODAL} overflow-hidden pointer-events-none ${
                isRightDrawer
                  ? "flex justify-end"
                  : "flex items-end sm:items-center justify-center p-0 sm:p-4"
              }`}
            >
              <Dialog.Content
                aria-describedby={description ? undefined : undefined}
                asChild
              >
                <motion.div
                  initial={
                    shouldReduceMotion
                      ? { opacity: 0 }
                      : isRightDrawer
                      ? { opacity: 0, x: "100%" }
                      : { opacity: 0, scale: 0.95, y: 16 }
                  }
                  animate={
                    shouldReduceMotion
                      ? { opacity: 1 }
                      : isRightDrawer
                      ? { opacity: 1, x: 0 }
                      : { opacity: 1, scale: 1, y: 0 }
                  }
                  exit={
                    shouldReduceMotion
                      ? { opacity: 0 }
                      : isRightDrawer
                      ? { opacity: 0, x: "100%" }
                      : { opacity: 0, scale: 0.95, y: 16 }
                  }
                  transition={modalSpringTransition}
                  className={
                    isRightDrawer
                      ? `pointer-events-auto h-full max-h-screen w-full ${maxWidth} flex flex-col rounded-l-2xl border-l border-border bg-card text-foreground shadow-2xl shadow-black/20 dark:shadow-black/95 overflow-hidden font-sans pb-[calc(1rem+env(safe-area-inset-bottom))] ${className}`
                      : `pointer-events-auto w-full ${maxWidth} h-auto max-h-[90dvh] sm:max-h-[85vh] flex flex-col rounded-2xl bg-card border border-border text-foreground shadow-2xl dark:shadow-[0_24px_64px_rgba(0,0,0,0.95)] overflow-hidden font-sans ${className}`
                  }
                >
                  {/* Radix Accessible Title (Always present, visually hidden if no custom title) */}
                  {!title && (
                    <Dialog.Title className="sr-only">Dialog Window</Dialog.Title>
                  )}

                  {/* Header */}
                  {(title || description) ? (
                    <div
                      className={`shrink-0 flex items-start justify-between p-4 sm:p-5 border-b border-border bg-card ${headerClassName}`}
                    >
                      <div className="space-y-1 pr-6 min-w-0">
                        {title && (
                          <Dialog.Title className="text-base sm:text-lg font-bold tracking-tight text-foreground font-sans break-words">
                            {title}
                          </Dialog.Title>
                        )}
                        {description && (
                          <Dialog.Description className="text-xs text-muted-foreground font-sans leading-relaxed block">
                            {description}
                          </Dialog.Description>
                        )}
                      </div>
                      <Dialog.Close asChild>
                        <button
                          type="button"
                          onClick={onClose}
                          className="relative rounded-xl p-2 min-w-[44px] min-h-[44px] inline-flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted active:scale-[0.98] transition-all cursor-pointer focus:outline-none focus-visible:ring-2 focus-visible:ring-emerald-700 dark:focus-visible:ring-emerald-400 touch-manipulation"
                          aria-label="Close dialog"
                        >
                          <X className="w-4 h-4" />
                        </button>
                      </Dialog.Close>
                    </div>
                  ) : (
                    <div className="absolute top-3 right-3 z-10">
                      <Dialog.Close asChild>
                        <button
                          type="button"
                          onClick={onClose}
                          className="relative rounded-xl p-2 min-w-[44px] min-h-[44px] inline-flex items-center justify-center bg-card border border-border text-muted-foreground hover:text-foreground hover:bg-muted active:scale-[0.98] transition-all cursor-pointer focus:outline-none focus-visible:ring-2 focus-visible:ring-emerald-700 dark:focus-visible:ring-emerald-400 touch-manipulation shadow-md"
                          aria-label="Close dialog"
                        >
                          <X className="w-4 h-4" />
                        </button>
                      </Dialog.Close>
                    </div>
                  )}

                  {/* Scrollable Content Region (min-h-0 prevents flex overflow clipping) */}
                  <div
                    className={`flex-1 min-h-0 overflow-y-auto overscroll-contain p-4 sm:p-5 ${
                      bodyClassName || ""
                    }`}
                  >
                    {children}
                  </div>

                  {/* Reachable Pinned Footer with Safe-Area Inset */}
                  {footer && (
                    <div
                      className={`shrink-0 p-3.5 sm:p-4 border-t border-border bg-card flex items-center justify-between gap-3 pb-[calc(0.75rem+env(safe-area-inset-bottom))] sm:pb-4 ${footerClassName}`}
                    >
                      {footer}
                    </div>
                  )}
                </motion.div>
              </Dialog.Content>
            </div>
          </Dialog.Portal>
        )}
      </AnimatePresence>
    </Dialog.Root>
  );
}

