// components/ui/button.tsx — Holy Trinity Shared Button Primitive
// Strictly adheres to Emil Kowalski & Apple physics:
// - Tactile active:scale-[0.98] compression
// - Electric Amethyst primary / Recessed Obsidian secondary
// - Accessible loading state with aria-busy
// - 44px minimum mobile hit targets via touch target expansion (after:absolute after:-inset-*) without desktop visual bloating
// - touch-manipulation to prevent mobile tap delay

"use client";

import * as React from "react";
import { Loader2 } from "lucide-react";
import { DESIGN_TOKENS } from "./tokens";

export type ButtonVariant =
  | "primary"
  | "secondary"
  | "destructive"
  | "ghost"
  | "outline"
  | "subtle";

export type ButtonSize = "sm" | "md" | "lg" | "icon" | "icon-sm";

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  isLoading?: boolean;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className = "",
      variant = "primary",
      size = "md",
      isLoading = false,
      disabled = false,
      leftIcon,
      rightIcon,
      children,
      type = "button",
      ...props
    },
    ref
  ) => {
    const isInteractive = !disabled && !isLoading;

    const variantStyles: Record<ButtonVariant, string> = {
      primary:
        "bg-emerald-600 hover:bg-emerald-500 text-white dark:bg-emerald-500 dark:hover:bg-emerald-400 dark:text-zinc-950 shadow-sm border border-emerald-600/30 dark:border-emerald-500/30 font-semibold",
      secondary:
        "bg-card dark:bg-[#0b0c10] text-[var(--foreground)] hover:bg-muted dark:hover:bg-white/[0.06] border border-border dark:border-white/[0.08] shadow-xs font-medium",
      subtle:
        "bg-muted dark:bg-white/[0.03] text-[var(--foreground)] hover:bg-muted/80 dark:hover:bg-white/[0.07] border border-border dark:border-white/[0.06] font-medium",
      outline:
        "bg-transparent text-[var(--foreground)] hover:bg-muted dark:hover:bg-white/[0.04] border border-border dark:border-white/[0.1] font-medium",
      destructive:
        "bg-rose-500/10 hover:bg-rose-500/20 text-rose-700 dark:text-rose-300 border border-rose-500/30 font-medium",
      ghost:
        "bg-transparent text-[var(--foreground)] hover:bg-muted dark:hover:bg-white/[0.05] border border-transparent font-medium",
    };

    // Mobile touch targets expand via pseudo-elements without inflating desktop density
    const sizeStyles: Record<ButtonSize, string> = {
      sm: "px-2.5 py-1 text-xs rounded-lg min-h-[32px] gap-1.5 after:absolute after:-inset-1.5 sm:after:hidden",
      md: "px-3.5 py-2 text-xs sm:text-sm rounded-xl min-h-[38px] gap-2 after:absolute after:-inset-1 sm:after:hidden",
      lg: "px-5 py-2.5 text-sm sm:text-base rounded-xl min-h-[44px] gap-2.5",
      icon: "w-9 h-9 min-w-[36px] min-h-[36px] rounded-xl p-0 flex items-center justify-center after:absolute after:-inset-1.5 sm:after:hidden",
      "icon-sm": "w-7 h-7 min-w-[28px] min-h-[28px] rounded-lg p-0 flex items-center justify-center after:absolute after:-inset-2 sm:after:hidden",
    };

    return (
      <button
        ref={ref}
        type={type}
        disabled={!isInteractive}
        aria-busy={isLoading}
        className={`relative inline-flex items-center justify-center select-none font-sans font-medium transition-all duration-150 ease-out touch-manipulation cursor-pointer ${
          isInteractive
            ? "active:scale-[0.98] cursor-pointer"
            : "opacity-50 cursor-not-allowed pointer-events-none"
        } ${DESIGN_TOKENS.borders.focus} ${variantStyles[variant]} ${
          sizeStyles[size]
        } ${className}`}
        {...props}
      >
        {isLoading && (
          <Loader2
            className={`w-3.5 h-3.5 animate-spin shrink-0 ${
              children ? "mr-1.5" : ""
            }`}
          />
        )}
        {!isLoading && leftIcon && (
          <span className="shrink-0 flex items-center">{leftIcon}</span>
        )}
        {children && <span>{children}</span>}
        {!isLoading && rightIcon && (
          <span className="shrink-0 flex items-center">{rightIcon}</span>
        )}
      </button>
    );
  }
);

Button.displayName = "Button";

