// components/ui/confirm-dialog.tsx — Reusable confirmation dialog built on AnimatedModal + Button.
// Usage:
//   <ConfirmDialog isOpen={!!pending} title="Delete item?" description="..."
//     confirmLabel="Delete" destructive isLoading={busy}
//     onConfirm={doDelete} onCancel={() => setPending(null)} />

"use client";

import * as React from "react";
import { AnimatedModal } from "./modal";
import { Button } from "./button";

export interface ConfirmDialogProps {
  isOpen: boolean;
  onConfirm: () => void | Promise<void>;
  onCancel: () => void;
  title: React.ReactNode;
  description?: React.ReactNode;
  confirmLabel?: string;
  cancelLabel?: string;
  /** Styles the confirm button as destructive. */
  destructive?: boolean;
  /** Disables both buttons and shows a spinner on confirm. */
  isLoading?: boolean;
}

export function ConfirmDialog({
  isOpen,
  onConfirm,
  onCancel,
  title,
  description,
  confirmLabel = "Confirm",
  cancelLabel = "Cancel",
  destructive = false,
  isLoading = false,
}: ConfirmDialogProps) {
  return (
    <AnimatedModal
      isOpen={isOpen}
      onClose={() => {
        if (!isLoading) onCancel();
      }}
      title={title}
      description={description}
      maxWidth="max-w-sm"
      footerClassName="justify-end"
      footer={
        <>
          <Button variant="secondary" onClick={onCancel} disabled={isLoading}>
            {cancelLabel}
          </Button>
          <Button
            variant={destructive ? "destructive" : "primary"}
            onClick={() => void onConfirm()}
            isLoading={isLoading}
          >
            {confirmLabel}
          </Button>
        </>
      }
    >
      {/* Body intentionally minimal; the description carries the message. */}
      <span className="sr-only">Please confirm this action.</span>
    </AnimatedModal>
  );
}

