  activeUnitsCount: number;
  pendingReviewItemsCount: number;
  totalOrdersCount: number;
  totalGmv: number;
  wholesaleLiabilities: number;
  disputeCount: number;
  systemHealth: {
    status: "HEALTHY" | "DEGRADED";
    database: "CONNECTED" | "ERROR";
    uptimeSeconds: number;
  };
}

interface OrderItem {
  id: string;
  code: string;
  resellerId: string;
  resellerName: string;
  supplierId: string;
  supplierName: string;
  itemId: string;
  itemName: string;
  retailPrice: number;
  wholesaleCost: number;
  grossProfit: number;
  status: "PENDING" | "RESERVED" | "PAID" | "FULFILLED" | "REFUNDED" | "CANCELLED";
  createdAt: string;
  fulfilledAt: string | null;
}

export default function AdminDashboardPage() {
  const [financials, setFinancials] = useState<FinancialMetrics | null>(null);
  const [overview, setOverview] = useState<AdminOverview | null>(null);
  const [orders, setOrders] = useState<OrderItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [telegramDrawerOpen, setTelegramDrawerOpen] = useState(false);

  // Dynamic filter state
  const [statusFilter, setStatusFilter] = useState<"ALL" | "PENDING" | "PAID" | "DELIVERED">("ALL");
  const [searchQuery, setSearchQuery] = useState("");

  // Actionable Operations Queue State (Monitoring-First)
  const [actionableLoading, setActionableLoading] = useState(true);
  const [actionableCounts, setActionableCounts] = useState<{
    pendingDeposits: number;
    pendingPayouts: number;
    heldLiabilitiesCount: number;
    heldLiabilitiesTotal: number;
    paymentsNeedingReview: number;
  }>({
    pendingDeposits: 0,
    pendingPayouts: 0,
    heldLiabilitiesCount: 0,
    heldLiabilitiesTotal: 0,
    paymentsNeedingReview: 0,
  });
  const [actionableErrors, setActionableErrors] = useState<{
    deposits?: boolean;
    payouts?: boolean;
    liabilities?: boolean;
    watchdog?: boolean;
  }>({});
  const [lastCheckedTime, setLastCheckedTime] = useState<string | null>(null);
  const [syncingTelegram, setSyncingTelegram] = useState(false);
  const [syncMessage, setSyncMessage] = useState<string | null>(null);

  async function loadActionableQueue() {
    setActionableLoading(true);
    const errors: { deposits?: boolean; payouts?: boolean; liabilities?: boolean; watchdog?: boolean } = {};

    await Promise.allSettled([
      // 1. Inbound deposits
      fetch("/api/admin/supplier-deposits?status=PENDING", { credentials: "include" })
        .then((r) => {
          if (!r.ok) throw new Error("HTTP " + r.status);
          return r.json();
        })
        .then((d) => {
          if (d?.pendingCount !== undefined) {
            setActionableCounts((prev) => ({ ...prev, pendingDeposits: d.pendingCount }));
          } else if (Array.isArray(d?.deposits)) {
            setActionableCounts((prev) => ({ ...prev, pendingDeposits: d.deposits.length }));
          }
        })
        .catch(() => {
          errors.deposits = true;
        }),

      // 2. Pending payouts
      fetch("/api/admin/payouts", { credentials: "include" })
        .then((r) => {
          if (!r.ok) throw new Error("HTTP " + r.status);
          return r.json();
        })
        .then((d) => {
          const list = d?.payouts || d?.data || [];
          const reqCount = list.filter((p: any) => p.status === "REQUESTED" || p.status === "PENDING").length;
          setActionableCounts((prev) => ({ ...prev, pendingPayouts: reqCount }));
        })
        .catch(() => {
          errors.payouts = true;
        }),

      // 3. Held liabilities
      fetch("/api/admin/supplier-liabilities?status=HELD", { credentials: "include" })
        .then((r) => {
          if (!r.ok) throw new Error("HTTP " + r.status);
          return r.json();
        })
        .then((d) => {
          const liabilities = d?.liabilities || [];
          const totalMinor = liabilities.reduce((sum: number, l: any) => sum + (Number(l.amountMinor) || 0), 0);
          setActionableCounts((prev) => ({
            ...prev,
            heldLiabilitiesCount: liabilities.length,
            heldLiabilitiesTotal: totalMinor / 100,
          }));
        })
        .catch(() => {
          errors.liabilities = true;
        }),

      // 4. Watchdog review payments
      fetch("/api/admin/p2p-watchdog", { credentials: "include" })
        .then((r) => {
          if (!r.ok) throw new Error("HTTP " + r.status);
          return r.json();
        })
        .then((d) => {
          const sessions = d?.recentSessions || d?.sessions || [];
          const reviewCount = sessions.filter((s: any) => s.status === "NEEDS_REVIEW" || s.status === "UNMATCHED").length;
          setActionableCounts((prev) => ({ ...prev, paymentsNeedingReview: reviewCount }));
        })
        .catch(() => {
          errors.watchdog = true;
        }),
    ]);

    setActionableErrors(errors);
    setActionableLoading(false);
    setLastCheckedTime(new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" }));
  }

  async function triggerTelegramSync() {
    if (syncingTelegram) return;
    setSyncingTelegram(true);
    setSyncMessage(null);
    try {
      const res = await fetch("/api/admin/catalog/sync", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
      });
      const data = await res.json();
      if (res.ok && data.success) {
        setSyncMessage("Stock channel updated successfully!");
      } else {
        setSyncMessage(data.error || "Sync failed. Verify bot permissions.");
      }
    } catch {
      setSyncMessage("Network error syncing Telegram channel.");
    } finally {
      setSyncingTelegram(false);
      setTimeout(() => setSyncMessage(null), 4000);
    }
  }

  // Store Expenses state & modal
  const [showExpenseModal, setShowExpenseModal] = useState(false);
  const [expenses, setExpenses] = useState<any[]>([]);
  const [loadingExpenses, setLoadingExpenses] = useState(false);
  const [expenseSubmitting, setExpenseSubmitting] = useState(false);
  const [newCategory, setNewCategory] = useState<string>("Hosting / Domains");
  const [newDesc, setNewDesc] = useState<string>("");
  const [newAmount, setNewAmount] = useState<string>("");
  const [newDate, setNewDate] = useState<string>("");
  const [expenseError, setExpenseError] = useState<string | null>(null);

  async function openExpenseModal() {
    setShowExpenseModal(true);
    setLoadingExpenses(true);
    setExpenseError(null);
    try {
      const res = await fetch("/api/admin/expenses", {
        credentials: "include",
      });
      const data = await res.json();
      if (data.expenses) setExpenses(data.expenses);
    } catch {
      setExpenses([]);
    } finally {
      setLoadingExpenses(false);
    }
  }

  async function handleCreateExpense(e: React.FormEvent) {
    e.preventDefault();
    if (!newDesc.trim() || !newAmount || Number(newAmount) <= 0) return;
    setExpenseSubmitting(true);
    setExpenseError(null);

    try {
      const res = await fetch("/api/admin/expenses", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          category: newCategory,
          description: newDesc.trim(),
          amount: Number(newAmount),
          date: newDate || undefined,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Failed to record expense");

      setNewDesc("");
      setNewAmount("");
      setNewDate("");
      const expRes = await fetch("/api/admin/expenses", {
        credentials: "include",
      });
      const expData = await expRes.json();
      if (expData.expenses) setExpenses(expData.expenses);
      fetchDashboardData(true);
    } catch (err: any) {
      setExpenseError(err.message || "Failed to record expense");
    } finally {
      setExpenseSubmitting(false);
    }
  }

  async function handleDeleteExpense(id: string) {
    if (!window.confirm("Are you sure you want to delete this operational expense record?")) return;
    try {
      const res = await fetch(`/api/admin/expenses?id=${encodeURIComponent(id)}`, {
        method: "DELETE",
        credentials: "include",
      });
      if (res.ok) {
        setExpenses((prev) => prev.filter((e) => e.id !== id));
        fetchDashboardData(true);
      }
    } catch {}
  }

  useEffect(() => {
    fetchDashboardData();
    loadActionableQueue();

    const intervalId = setInterval(() => {
      if (typeof document !== "undefined" && document.hidden) return;
      fetchDashboardData(true);
      loadActionableQueue();
    }, 15000);

    const handleFocus = () => {
      if (typeof document !== "undefined" && !document.hidden) {
        fetchDashboardData(true);
        loadActionableQueue();
      }
    };

    if (typeof window !== "undefined") {
      window.addEventListener("focus", handleFocus);
    }

    return () => {
      clearInterval(intervalId);
      if (typeof window !== "undefined") {
        window.removeEventListener("focus", handleFocus);
      }
    };
  }, []);

  async function fetchDashboardData(isRefresh = false) {
    if (isRefresh) setRefreshing(true);
    else setLoading(true);
    setError(null);

    try {
      const [finRes, ovRes, ordRes] = await Promise.all([
        fetch("/api/admin/financials", { credentials: "include" }).then((r) => r.json()).catch(() => ({})),
        fetch("/api/admin/overview", { credentials: "include" }).then((r) => r.json()).catch(() => ({})),
        fetch("/api/admin/orders", { credentials: "include" }).then((r) => r.json()).catch(() => ({})),
      ]);

      if (finRes?.financials || finRes?.data) setFinancials(finRes.financials || finRes.data);
      if (ovRes?.overview || ovRes?.data) setOverview(ovRes.overview || ovRes.data);
      const ordersList = Array.isArray(ordRes?.orders)
        ? ordRes.orders
        : Array.isArray(ordRes?.data)
        ? ordRes.data
        : [];
      setOrders(ordersList);
    } catch (err: any) {
      setError((err?.message ?? "").trim() || "Failed to load admin telemetry");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }

  // Filter counts
  const filterCounts = useMemo(() => {
    return {
      ALL: orders.length,
      PENDING: orders.filter((o) => o.status === "PENDING" || o.status === "RESERVED").length,
      PAID: orders.filter((o) => o.status === "PAID").length,
      DELIVERED: orders.filter((o) => o.status === "FULFILLED").length,
    };
  }, [orders]);

  // Dynamically filtered feed
  const filteredOrders = useMemo(() => {
    return orders.filter((order) => {
      // Status filtering
      if (statusFilter === "PENDING") {
        if (order.status !== "PENDING" && order.status !== "RESERVED") return false;
      } else if (statusFilter === "PAID") {
        if (order.status !== "PAID") return false;
      } else if (statusFilter === "DELIVERED") {
        if (order.status !== "FULFILLED") return false;
      }

      // Search query filtering
      if ((searchQuery ?? "").trim()) {
        const query = searchQuery.toLowerCase();
        const codeMatch = order.code?.toLowerCase().includes(query);
        const itemMatch = order.itemName?.toLowerCase().includes(query);
        const resellerMatch = order.resellerName?.toLowerCase().includes(query);
        const supplierMatch = order.supplierName?.toLowerCase().includes(query);
        if (!codeMatch && !itemMatch && !resellerMatch && !supplierMatch) {
          return false;
        }
      }

      return true;
    });
  }, [orders, statusFilter, searchQuery]);

  // Derived metrics
  const grossMargin = financials?.netPlatformRevenue ?? 0;
  const gmv = financials?.grossMerchandiseVolume ?? 0;
  const totalStoreExpenses = financials?.totalStoreExpenses ?? 0;
  const netProfit = financials?.netProfit ?? Number((grossMargin - totalStoreExpenses).toFixed(2));
  const marginPercentage = gmv > 0 ? ((grossMargin / gmv) * 100).toFixed(1) : "0.0";
  const netProfitMarginPercent = gmv > 0 ? ((netProfit / gmv) * 100).toFixed(1) : "0.0";
  const clearedBalances = financials?.supplierSettlementLiabilities?.clearedBalance ?? 0;
  const pendingEscrow = financials?.supplierSettlementLiabilities?.pendingEscrow ?? 0;
  const liveInventoryUnits = overview?.activeUnitsCount ?? 0;
  const isReconHealthy = financials?.reconciliation?.isHealthy ?? true;

  // Compute total actionable count
  const totalActionableIssues =
    (actionableCounts.paymentsNeedingReview || 0) +
    (((overview as any)?.storeAlerts?.pendingOrdersCount ?? filterCounts.PENDING) || 0) +
    (((overview as any)?.storeAlerts?.lowStockCount || 0)) +
    (actionableCounts.pendingDeposits || 0) +
    (actionableCounts.pendingPayouts || 0);

  const hasAnyQueueError = Boolean(
    actionableErrors.watchdog ||
    actionableErrors.deposits ||
    actionableErrors.payouts
  );

  return (
    <div className="space-y-6 w-full">
      {/* Top Header & Telemetry Status */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-3 border-b border-border/60">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold tracking-tight text-foreground font-sans">
            Overview
          </h1>
          <p className="text-xs text-muted-foreground mt-0.5">
            Real-time operations, inventory velocity, and financial health.
          </p>
        </div>

        <div className="flex items-center space-x-3 self-start sm:self-auto flex-wrap">
          {/* Truthful Service Health Status Bar */}
          <div className="flex items-center space-x-2 px-3 py-1.5 rounded-xl bg-card border border-border text-xs font-mono text-foreground">
            <span className={`inline-block w-2 h-2 rounded-full ${
              overview?.systemHealth?.database === "CONNECTED" ? "bg-emerald-500" : overview?.systemHealth?.database === "ERROR" ? "bg-rose-500" : "bg-zinc-400"
            }`} />
            <span className="text-muted-foreground">
              {overview?.systemHealth?.database === "CONNECTED"
                ? "Database connected"
                : overview?.systemHealth?.database === "ERROR"
                ? "Database error"
                : "Database: Not checked"}
            </span>
            <span className="text-border">&bull;</span>
            <span className={actionableErrors.watchdog ? "text-amber-500" : actionableCounts.paymentsNeedingReview > 0 ? "text-rose-400 font-semibold" : "text-emerald-500"}>
              {actionableErrors.watchdog
                ? "Payments: Unavailable"
                : actionableCounts.paymentsNeedingReview > 0
                ? `${actionableCounts.paymentsNeedingReview} review needed`
                : "Payments: Monitored"}
            </span>
            {lastCheckedTime && (
              <>
                <span className="text-border">&bull;</span>
                <span className="text-[10px] text-muted-foreground">{lastCheckedTime}</span>
              </>
            )}
          </div>

          <button
            onClick={() => {
              fetchDashboardData(true);
              loadActionableQueue();
            }}
            disabled={refreshing || loading || actionableLoading}
            aria-label="Refresh telemetry data"
            className="p-2 rounded-xl bg-card border border-border text-muted-foreground hover:text-foreground hover:bg-muted transition-colors disabled:opacity-50 cursor-pointer"
            title="Refresh all monitors"
          >
            <RefreshCw className={`w-4 h-4 ${(refreshing || actionableLoading) ? "animate-spin text-foreground" : ""}`} />
          </button>
        </div>
      </div>

      {error && (
        <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-400 text-xs flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <AlertCircle className="w-4 h-4 flex-shrink-0" />
            <span>{error}</span>
          </div>
          <button
            onClick={() => fetchDashboardData()}
            className="underline hover:no-underline font-mono text-[11px] cursor-pointer"
          >
            Retry
          </button>
        </div>
      )}

      {/* ── 1. PRIMARY: NEEDS ATTENTION (OPERATIONS QUEUE RANKED BY CONSEQUENCE) ── */}
      <div className="rounded-xl border border-border/70 bg-card p-4 space-y-3">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-3 border-b border-border">
          <div>
            <div className="flex items-center space-x-2">
              <span className={`w-2.5 h-2.5 rounded-full ${totalActionableIssues > 0 ? "bg-amber-500 animate-pulse" : "bg-emerald-500"}`} />
              <h2 className="text-sm font-bold text-foreground font-sans uppercase tracking-wider">
                Needs attention
              </h2>
            </div>
            <p className="text-xs text-muted-foreground mt-0.5">
              Actionable tasks ranked by consequence: payment verification, order fulfillment, stock levels, and partner reviews.
            </p>
          </div>

          <div className="flex items-center gap-2">
            {syncMessage && (
              <span className="text-[11px] font-mono text-emerald-400 bg-emerald-500/10 border border-emerald-500/20 px-2 py-1 rounded-lg">
                {syncMessage}
              </span>
            )}
            <button
              onClick={triggerTelegramSync}
              disabled={syncingTelegram}
              className="flex items-center space-x-1.5 px-3 py-1.5 rounded-xl border border-sky-500/30 bg-sky-500/10 hover:bg-sky-500/20 text-xs font-mono text-sky-300 transition-colors disabled:opacity-50 cursor-pointer"
              title="Broadcast verified stock board to Telegram"
            >
              <RefreshCw className={`w-3 h-3 ${syncingTelegram ? "animate-spin text-sky-400" : ""}`} />
              <span>{syncingTelegram ? "Broadcasting..." : "Broadcast stock"}</span>
            </button>
          </div>
        </div>

        {/* Quiet state when all checked sources are clear */}
        {!actionableLoading && totalActionableIssues === 0 && !hasAnyQueueError && (
          <div className="p-8 text-center space-y-2 rounded-xl bg-muted/30 border border-border">
            <CheckCircle2 className="w-8 h-8 mx-auto text-emerald-500" />
            <div className="text-sm font-semibold text-foreground">No issues found in checked sources</div>
            <p className="text-xs text-muted-foreground max-w-md mx-auto">
              All 5 monitored operational queues (payments, orders, stock, supplier deposits, and payouts) are clear as of {lastCheckedTime || "latest check"}.
            </p>
          </div>
        )}

        {/* Actionable cards ranked by consequence */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3">
          {/* Priority 1: Payment Review (Highest Consequence) */}
          <Link
            href="/admin/p2p-watchdog"
            className="p-4 rounded-xl border border-border bg-muted/40 hover:border-emerald-500/30 hover:bg-card transition-all flex flex-col justify-between group"
          >
            <div>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-mono uppercase tracking-wider text-muted-foreground font-semibold">1. Payment review</span>
                {actionableErrors.watchdog ? (
                  <span className="px-2 py-0.5 rounded-full text-[10px] font-mono bg-rose-500/10 text-rose-400 border border-rose-500/20">
                    Unavailable
                  </span>
                ) : (
                  <span className={`px-2 py-0.5 rounded-full text-[10px] font-mono font-bold ${
                    actionableCounts.paymentsNeedingReview > 0
                      ? "bg-rose-500/10 text-rose-400 border border-rose-500/20"
                      : "bg-muted text-muted-foreground"
                  }`}>
                    {actionableCounts.paymentsNeedingReview > 0 ? `${actionableCounts.paymentsNeedingReview} Alert` : "Clear"}
                  </span>
                )}
              </div>
              <div className="text-lg font-bold font-mono text-foreground">
                {actionableErrors.watchdog ? "Error" : `${actionableCounts.paymentsNeedingReview} ${actionableCounts.paymentsNeedingReview === 1 ? "Audit" : "Audits"}`}
              </div>
              <p className="text-[11px] text-muted-foreground mt-1">Ambiguous or unmatched payment transactions</p>
            </div>
            <div className="mt-3 pt-2 border-t border-border flex items-center justify-between text-xs text-sky-400 group-hover:text-sky-300 font-medium">
              <span>Inspect payments</span>
              <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
            </div>
          </Link>

          {/* Priority 2: Customer Orders Requiring Delivery */}
          <Link
            href="/admin/orders?status=PENDING"
            className="p-4 rounded-xl border border-border bg-muted/40 hover:border-emerald-500/30 hover:bg-card transition-all flex flex-col justify-between group"
          >
            <div>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-mono uppercase tracking-wider text-muted-foreground font-semibold">2. Order delivery</span>
                <span className={`px-2 py-0.5 rounded-full text-[10px] font-mono font-bold ${
                  ((overview as any)?.storeAlerts?.pendingOrdersCount ?? filterCounts.PENDING) > 0
                    ? "bg-amber-500/10 text-amber-400 border border-amber-500/20"
                    : "bg-muted text-muted-foreground"
                }`}>
                  {((overview as any)?.storeAlerts?.pendingOrdersCount ?? filterCounts.PENDING)} Pending
                </span>
              </div>
              <div className="text-lg font-bold font-mono text-foreground">
                {((overview as any)?.storeAlerts?.pendingOrdersCount ?? filterCounts.PENDING)} Orders
              </div>
              <p className="text-[11px] text-muted-foreground mt-1">Confirmed payments awaiting fulfillment</p>
            </div>
            <div className="mt-3 pt-2 border-t border-border flex items-center justify-between text-xs text-amber-400 group-hover:text-amber-300 font-medium">
              <span>Fulfill orders</span>
              <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
            </div>
          </Link>

          {/* Priority 3: Stock Alert / Restock Conflicts */}
          <Link
            href="/admin/inventory"
            className="p-4 rounded-xl border border-border bg-muted/40 hover:border-emerald-500/30 hover:bg-card transition-all flex flex-col justify-between group"
          >
            <div>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-mono uppercase tracking-wider text-muted-foreground font-semibold">3. Stock alerts</span>
                <span className={`px-2 py-0.5 rounded-full text-[10px] font-mono font-bold ${
                  ((overview as any)?.storeAlerts?.lowStockCount ?? 0) > 0
                    ? "bg-rose-500/10 text-rose-400 border border-rose-500/20"
                    : "bg-muted text-muted-foreground"
                }`}>
                  {((overview as any)?.storeAlerts?.lowStockCount ?? 0)} Low
                </span>
              </div>
              <div className="text-lg font-bold font-mono text-foreground">
                {((overview as any)?.storeAlerts?.lowStockCount ?? 0)} Items
              </div>
              <p className="text-[11px] text-muted-foreground mt-1">Products with low or depleted vault inventory</p>
            </div>
            <div className="mt-3 pt-2 border-t border-border flex items-center justify-between text-xs text-rose-400 group-hover:text-rose-300 font-medium">
              <span>Restock vault</span>
              <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
            </div>
          </Link>

          {/* Priority 4: Inbound Supplier Stock Deposits */}
          <Link
            href="/admin/suppliers?tab=verification"
            className="p-4 rounded-xl border border-border bg-muted/40 hover:border-emerald-500/30 hover:bg-card transition-all flex flex-col justify-between group"
          >
            <div>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-mono uppercase tracking-wider text-muted-foreground font-semibold">4. Inbound stock</span>
                {actionableErrors.deposits ? (
                  <span className="px-2 py-0.5 rounded-full text-[10px] font-mono bg-rose-500/10 text-rose-400 border border-rose-500/20">
                    Unavailable
                  </span>
                ) : (
                  <span className={`px-2 py-0.5 rounded-full text-[10px] font-mono font-bold ${
                    actionableCounts.pendingDeposits > 0
                      ? "bg-amber-500/10 text-amber-400 border border-amber-500/20"
                      : "bg-muted text-muted-foreground"
                  }`}>
                    {actionableCounts.pendingDeposits} Pending
                  </span>
                )}
              </div>
              <div className="text-lg font-bold font-mono text-foreground">
                {actionableErrors.deposits ? "Error" : `${actionableCounts.pendingDeposits} ${actionableCounts.pendingDeposits === 1 ? "Batch" : "Batches"}`}
              </div>
              <p className="text-[11px] text-muted-foreground mt-1">Submitted supply batches awaiting verification</p>
