                        <td className="py-3 px-3 text-right text-foreground whitespace-nowrap font-medium">
                          ₱{Number(order?.retailPrice ?? 0).toFixed(2)}
                        </td>
                        <td className="py-3 px-3 text-right text-muted-foreground whitespace-nowrap">
                          ₱{Number(order?.wholesaleCost ?? 0).toFixed(2)}
                        </td>
                        <td className="py-3 px-3 text-right text-emerald-500 dark:text-emerald-400 whitespace-nowrap font-semibold">
                          ₱{Number(order?.grossProfit ?? 0).toFixed(2)}
                        </td>
                        <td className="py-3 px-3 text-center whitespace-nowrap">
                          <span
                            className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-semibold uppercase ${
                              isFulfilled
                                ? "bg-emerald-500/10 text-emerald-500 dark:text-emerald-400 border border-emerald-500/20"
                                : isPaid
                                ? "bg-sky-500/10 text-sky-500 dark:text-sky-400 border border-sky-500/20"
                                : isPending
                                ? "bg-amber-500/10 text-amber-500 dark:text-amber-400 border border-amber-500/20"
                                : "bg-rose-500/10 text-rose-500 dark:text-rose-400 border border-rose-500/20"
                            }`}
                          >
                            {order.status}
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      {/* Store Operational Expenses & Net Profit Management Modal */}
      {showExpenseModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-150">
          <div className="relative w-full max-w-2xl rounded-2xl border border-border bg-card p-6 shadow-2xl space-y-6 max-h-[90vh] overflow-y-auto">
            {/* Modal Header */}
            <div className="flex items-center justify-between border-b border-border pb-4">
              <div className="flex items-center space-x-2.5">
                <div className="w-8 h-8 rounded-xl bg-rose-500/10 border border-rose-500/20 flex items-center justify-center">
                  <Receipt className="w-4 h-4 text-rose-400" />
                </div>
                <div>
                  <h3 className="text-base font-bold text-foreground font-sans">
                    Store Operational Expenses &amp; Net Profit
                  </h3>
                  <p className="text-xs text-muted-foreground">
                    Record operational outflows (hosting, APIs, telecom) to compute true net platform profit
                  </p>
                </div>
              </div>
              <button
                onClick={() => setShowExpenseModal(false)}
                className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted transition-colors cursor-pointer"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Net Platform Profit Equation Summary */}
            <div className="p-4 rounded-xl border border-border bg-muted/40 grid grid-cols-3 gap-3 text-center font-mono text-xs">
              <div>
                <div className="text-[10px] text-muted-foreground uppercase">Gross Margin</div>
                <div className="text-sm font-bold text-foreground">₱{Number(grossMargin ?? 0).toFixed(2)}</div>
              </div>
              <div>
                <div className="text-[10px] text-rose-400 uppercase">- Store Expenses</div>
                <div className="text-sm font-bold text-rose-400">₱{Number(totalStoreExpenses ?? 0).toFixed(2)}</div>
              </div>
              <div>
                <div className="text-[10px] text-emerald-400 uppercase">= Net Profit</div>
                <div className="text-sm font-bold text-emerald-400">₱{Number(netProfit ?? 0).toFixed(2)}</div>
              </div>
            </div>

            {/* Add Expense Form */}
            <form onSubmit={handleCreateExpense} className="space-y-4 p-4 rounded-2xl border border-border bg-muted/30">
              <div className="text-xs font-semibold text-foreground flex items-center space-x-1.5 font-mono">
                <Plus className="w-3.5 h-3.5 text-rose-400" />
                <span>Record New Operational Outflow</span>
              </div>

              {expenseError && (
                <div className="p-3 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-400 text-xs flex items-center space-x-2">
                  <AlertCircle className="w-4 h-4 flex-shrink-0" />
                  <span>{expenseError}</span>
                </div>
              )}

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-[10px] font-mono uppercase text-muted-foreground mb-1">Category</label>
                  <select
                    value={newCategory}
                    onChange={(e) => setNewCategory(e.target.value)}
                    className="w-full px-3 py-1.5 rounded-xl border border-border bg-card text-xs text-foreground focus:outline-none focus:border-ring font-mono"
                  >
                    <option value="Hosting / Domains">Hosting / Domains (Vercel, Cloudflare, etc.)</option>
                    <option value="API Services">API Services (OpenAI, DeepSeek, Upstash)</option>
                    <option value="Product Purchases">Product Purchases / Seed Stock</option>
                    <option value="Telecom">Telecom / SMS Verification</option>
                    <option value="Other">Other Operational Outflow</option>
                  </select>
                </div>

                <div>
                  <label className="block text-[10px] font-mono uppercase text-muted-foreground mb-1">Amount (₱ PHP)</label>
                  <input
                    type="number"
                    step="0.01"
                    required
                    min="0.01"
                    placeholder="e.g. 1500.00"
                    value={newAmount}
                    onChange={(e) => setNewAmount(e.target.value)}
                    className="w-full px-3 py-1.5 rounded-xl border border-border bg-card text-xs text-foreground font-mono focus:outline-none focus:border-ring"
                  />
                </div>

                <div className="sm:col-span-2">
                  <label className="block text-[10px] font-mono uppercase text-muted-foreground mb-1">Description</label>
                  <input
                    type="text"
                    required
                    placeholder="e.g. Vercel Pro Team monthly hosting & serverless compute"
                    value={newDesc}
                    onChange={(e) => setNewDesc(e.target.value)}
                    className="w-full px-3 py-1.5 rounded-xl border border-border bg-card text-xs text-foreground font-mono focus:outline-none focus:border-ring"
                  />
                </div>
              </div>

              <div className="flex justify-end pt-1">
                <button
                  type="submit"
                  disabled={expenseSubmitting || !newDesc.trim() || !newAmount}
                  className="px-4 py-2 rounded-xl bg-foreground hover:opacity-90 text-background text-xs font-semibold uppercase tracking-wider transition-opacity disabled:opacity-50 cursor-pointer shadow-sm"
                >
                  {expenseSubmitting ? "Recording..." : "Save Expense"}
                </button>
              </div>
            </form>

            {/* Expenses List */}
            <div className="space-y-3">
              <div className="flex items-center justify-between text-xs font-mono text-muted-foreground">
                <span>Recorded Store Expenses ({expenses.length})</span>
                <span>Total: ₱{Number(totalStoreExpenses ?? 0).toFixed(2)}</span>
              </div>

              {loadingExpenses ? (
                <div className="p-8 text-center text-xs font-mono text-muted-foreground">Loading expense logs...</div>
              ) : expenses.length === 0 ? (
                <div className="p-8 text-center rounded-xl border border-border text-xs text-muted-foreground font-mono">
                  No store expenses recorded yet.
                </div>
              ) : (
                <div className="divide-y divide-border/50 max-h-56 overflow-y-auto rounded-xl border border-border bg-card font-mono text-xs">
                  {expenses.map((exp: any) => (
                    <div key={exp.id} className="p-3 flex items-center justify-between gap-3">
                      <div>
                        <div className="flex items-center space-x-2">
                          <span className="font-semibold text-foreground">{exp.description}</span>
                          <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-muted border border-border text-muted-foreground">
                            {exp.category}
                          </span>
                        </div>
                        <div className="text-[11px] text-muted-foreground mt-0.5">{exp.date || exp.created_at?.slice(0, 10)}</div>
                      </div>
                      <div className="flex items-center space-x-3">
                        <span className="font-bold text-rose-400">₱{Number(exp?.amount ?? 0).toFixed(2)}</span>
                        <button
                          onClick={() => handleDeleteExpense(exp.id)}
                          className="p-1 rounded text-muted-foreground hover:text-rose-400 transition-colors cursor-pointer"
                          title="Delete expense"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect, useMemo, useCallback, useRef } from "react";
import Link from "next/link";
import {
  TrendingUp,
  Wallet,
  Clock,
  Boxes,
  Key,
  ShoppingBag,
  Users,
  CreditCard,
  DollarSign,
  ArrowRight,
  ShieldCheck,
  Search,
  RefreshCw,
  CheckCircle2,
  AlertCircle,
  Package,
  Layers,
  Sparkles,
  Receipt,
  Plus,
  Trash2,
  X,
  AlertTriangle,
  FileText,
  ChevronDown,
  ClipboardList,
  Tag,
} from "lucide-react";
import { TelegramHealthCard } from "@/components/admin/telegram-health-card";

interface FinancialMetrics {
  grossMerchandiseVolume: number;
  totalWholesaleCost: number;
  netPlatformRevenue: number;
  totalStoreExpenses?: number;
  netProfit?: number;
  expensesByCategory?: Record<string, number>;
  totalOrdersCount: number;
  supplierSettlementLiabilities: {
    pendingEscrow: number;
    clearedBalance: number;
    totalPaidOut: number;
  };
  resellerCredits: {
    totalOutstandingBalance: number;
  };
  reconciliation?: {
    isHealthy: boolean;
    accountingEquation: {
      totalGrossMerchandiseVolume: number;
      totalWholesaleLiabilities: number;
      totalPlatformFees: number;
      variance: number;
    };
    cashPosition: {
      cashInflows: number;
      cashOutflows: number;
      netPlatformCash: number;
    };
    discrepancies: string[];
  };
}

interface AdminOverview {
  suppliersCount: number;
  resellersCount: number;
  activeUnitsCount: number;
  pendingReviewItemsCount: number;
  totalOrdersCount: number;
  totalGmv: number;
  wholesaleLiabilities: number;
  disputeCount: number;
  systemHealth: {
    status: "HEALTHY" | "DEGRADED";
    database: "CONNECTED" | "ERROR";
    uptimeSeconds: number;
  };
}

interface OrderItem {
  id: string;
  code: string;
  resellerId: string;
  resellerName: string;
  supplierId: string;
  supplierName: string;
  itemId: string;
  itemName: string;
  retailPrice: number;
  wholesaleCost: number;
  grossProfit: number;
  status: "PENDING" | "RESERVED" | "PAID" | "FULFILLED" | "REFUNDED" | "CANCELLED";
  createdAt: string;
  fulfilledAt: string | null;
}

export default function AdminDashboardPage() {
  const [financials, setFinancials] = useState<FinancialMetrics | null>(null);
  const [overview, setOverview] = useState<AdminOverview | null>(null);
  const [orders, setOrders] = useState<OrderItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [telegramDrawerOpen, setTelegramDrawerOpen] = useState(false);

  // Dynamic filter state
  const [statusFilter, setStatusFilter] = useState<"ALL" | "PENDING" | "PAID" | "DELIVERED">("ALL");
  const [searchQuery, setSearchQuery] = useState("");

  // Actionable Operations Queue State (Monitoring-First)
  const [actionableLoading, setActionableLoading] = useState(true);
  const [actionableCounts, setActionableCounts] = useState<{
    pendingDeposits: number;
    pendingPayouts: number;
    heldLiabilitiesCount: number;
    heldLiabilitiesTotal: number;
    paymentsNeedingReview: number;
  }>({
    pendingDeposits: 0,
    pendingPayouts: 0,
    heldLiabilitiesCount: 0,
    heldLiabilitiesTotal: 0,
    paymentsNeedingReview: 0,
  });
  const [actionableErrors, setActionableErrors] = useState<{
    deposits?: boolean;
    payouts?: boolean;
    liabilities?: boolean;
    watchdog?: boolean;
  }>({});
  const [lastCheckedTime, setLastCheckedTime] = useState<string | null>(null);
  const [syncingTelegram, setSyncingTelegram] = useState(false);
  const [syncMessage, setSyncMessage] = useState<string | null>(null);

  async function loadActionableQueue() {
    setActionableLoading(true);
    const errors: { deposits?: boolean; payouts?: boolean; liabilities?: boolean; watchdog?: boolean } = {};

    await Promise.allSettled([
      // 1. Inbound deposits
      fetch("/api/admin/supplier-deposits?status=PENDING", { credentials: "include" })
        .then((r) => {
          if (!r.ok) throw new Error("HTTP " + r.status);
          return r.json();
        })
        .then((d) => {
          if (d?.pendingCount !== undefined) {
            setActionableCounts((prev) => ({ ...prev, pendingDeposits: d.pendingCount }));
          } else if (Array.isArray(d?.deposits)) {
            setActionableCounts((prev) => ({ ...prev, pendingDeposits: d.deposits.length }));
          }
        })
        .catch(() => {
          errors.deposits = true;
        }),

      // 2. Pending payouts
      fetch("/api/admin/payouts", { credentials: "include" })
        .then((r) => {
          if (!r.ok) throw new Error("HTTP " + r.status);
          return r.json();
        })
        .then((d) => {
          const list = d?.payouts || d?.data || [];
          const reqCount = list.filter((p: any) => p.status === "REQUESTED" || p.status === "PENDING").length;
          setActionableCounts((prev) => ({ ...prev, pendingPayouts: reqCount }));
        })
        .catch(() => {
          errors.payouts = true;
        }),

      // 3. Held liabilities
      fetch("/api/admin/supplier-liabilities?status=HELD", { credentials: "include" })
        .then((r) => {
          if (!r.ok) throw new Error("HTTP " + r.status);
          return r.json();
        })
        .then((d) => {
          const liabilities = d?.liabilities || [];
          const totalMinor = liabilities.reduce((sum: number, l: any) => sum + (Number(l.amountMinor) || 0), 0);
          setActionableCounts((prev) => ({
            ...prev,
            heldLiabilitiesCount: liabilities.length,
            heldLiabilitiesTotal: totalMinor / 100,
          }));
        })
        .catch(() => {
          errors.liabilities = true;
        }),

      // 4. Watchdog review payments
      fetch("/api/admin/p2p-watchdog", { credentials: "include" })
        .then((r) => {
          if (!r.ok) throw new Error("HTTP " + r.status);
          return r.json();
        })
        .then((d) => {
          const sessions = d?.recentSessions || d?.sessions || [];
          const reviewCount = sessions.filter((s: any) => s.status === "NEEDS_REVIEW" || s.status === "UNMATCHED").length;
          setActionableCounts((prev) => ({ ...prev, paymentsNeedingReview: reviewCount }));
        })
        .catch(() => {
          errors.watchdog = true;
        }),
    ]);

    setActionableErrors(errors);
    setActionableLoading(false);
    setLastCheckedTime(new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" }));
  }

  async function triggerTelegramSync() {
    if (syncingTelegram) return;
    setSyncingTelegram(true);
    setSyncMessage(null);
    try {
      const res = await fetch("/api/admin/catalog/sync", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
      });
      const data = await res.json();
      if (res.ok && data.success) {
        setSyncMessage("Stock channel updated successfully!");
      } else {
        setSyncMessage(data.error || "Sync failed. Verify bot permissions.");
      }
    } catch {
      setSyncMessage("Network error syncing Telegram channel.");
    } finally {
      setSyncingTelegram(false);
      setTimeout(() => setSyncMessage(null), 4000);
    }
  }

  // Store Expenses state & modal
  const [showExpenseModal, setShowExpenseModal] = useState(false);
  const [expenses, setExpenses] = useState<any[]>([]);
  const [loadingExpenses, setLoadingExpenses] = useState(false);
  const [expenseSubmitting, setExpenseSubmitting] = useState(false);
  const [newCategory, setNewCategory] = useState<string>("Hosting / Domains");
  const [newDesc, setNewDesc] = useState<string>("");
  const [newAmount, setNewAmount] = useState<string>("");
  const [newDate, setNewDate] = useState<string>("");
  const [expenseError, setExpenseError] = useState<string | null>(null);

  async function openExpenseModal() {
    setShowExpenseModal(true);
    setLoadingExpenses(true);
    setExpenseError(null);
    try {
      const res = await fetch("/api/admin/expenses", {
        credentials: "include",
      });
      const data = await res.json();
      if (data.expenses) setExpenses(data.expenses);
    } catch {
      setExpenses([]);
    } finally {
      setLoadingExpenses(false);
    }
  }

  async function handleCreateExpense(e: React.FormEvent) {
    e.preventDefault();
    if (!newDesc.trim() || !newAmount || Number(newAmount) <= 0) return;
    setExpenseSubmitting(true);
    setExpenseError(null);

    try {
      const res = await fetch("/api/admin/expenses", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          category: newCategory,
          description: newDesc.trim(),
          amount: Number(newAmount),
          date: newDate || undefined,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Failed to record expense");

      setNewDesc("");
      setNewAmount("");
      setNewDate("");
      const expRes = await fetch("/api/admin/expenses", {
        credentials: "include",
      });
      const expData = await expRes.json();
      if (expData.expenses) setExpenses(expData.expenses);
      fetchDashboardData(true);
    } catch (err: any) {
      setExpenseError(err.message || "Failed to record expense");
    } finally {
      setExpenseSubmitting(false);
    }
  }

  const [expenseToDelete, setExpenseToDelete] = useState<any | null>(null);
  const [expenseDeleting, setExpenseDeleting] = useState(false);

  async function handleDeleteExpense() {
    if (!expenseToDelete) return;
    const id = expenseToDelete.id;
    setExpenseDeleting(true);
    try {
      const res = await fetch(`/api/admin/expenses?id=${encodeURIComponent(id)}`, {
        method: "DELETE",
        credentials: "include",
      });
      if (res.ok) {
        setExpenses((prev) => prev.filter((e) => e.id !== id));
        fetchDashboardData(true);
      }
    } catch {
    } finally {
      setExpenseDeleting(false);
      setExpenseToDelete(null);
    }
  }

  useEffect(() => {
    fetchDashboardData();
    loadActionableQueue();

    const intervalId = setInterval(() => {
      if (typeof document !== "undefined" && document.hidden) return;
      fetchDashboardData(true);
      loadActionableQueue();
    }, 15000);

    const handleFocus = () => {
      if (typeof document !== "undefined" && !document.hidden) {
        fetchDashboardData(true);
        loadActionableQueue();
      }
    };

    if (typeof window !== "undefined") {
      window.addEventListener("focus", handleFocus);
    }

    return () => {
      clearInterval(intervalId);
      if (typeof window !== "undefined") {
        window.removeEventListener("focus", handleFocus);
      }
    };
  }, []);

  async function fetchDashboardData(isRefresh = false) {
    if (isRefresh) setRefreshing(true);
    else setLoading(true);
    setError(null);

    try {
      const [finRes, ovRes, ordRes] = await Promise.all([
        fetch("/api/admin/financials", { credentials: "include" }).then((r) => r.json()).catch(() => ({})),
        fetch("/api/admin/overview", { credentials: "include" }).then((r) => r.json()).catch(() => ({})),
        fetch("/api/admin/orders", { credentials: "include" }).then((r) => r.json()).catch(() => ({})),
      ]);

      if (finRes?.financials || finRes?.data) setFinancials(finRes.financials || finRes.data);
      if (ovRes?.overview || ovRes?.data) setOverview(ovRes.overview || ovRes.data);
      const ordersList = Array.isArray(ordRes?.orders)
        ? ordRes.orders
        : Array.isArray(ordRes?.data)
        ? ordRes.data
        : [];
      setOrders(ordersList);
    } catch (err: any) {
      setError((err?.message ?? "").trim() || "Failed to load admin telemetry");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }

  // Filter counts
  const filterCounts = useMemo(() => {
    return {
      ALL: orders.length,
      PENDING: orders.filter((o) => o.status === "PENDING" || o.status === "RESERVED").length,
      PAID: orders.filter((o) => o.status === "PAID").length,
      DELIVERED: orders.filter((o) => o.status === "FULFILLED").length,
    };
  }, [orders]);

  // Dynamically filtered feed
  const filteredOrders = useMemo(() => {
    return orders.filter((order) => {
      // Status filtering
      if (statusFilter === "PENDING") {
        if (order.status !== "PENDING" && order.status !== "RESERVED") return false;
      } else if (statusFilter === "PAID") {
        if (order.status !== "PAID") return false;
      } else if (statusFilter === "DELIVERED") {
        if (order.status !== "FULFILLED") return false;
      }

      // Search query filtering
      if ((searchQuery ?? "").trim()) {
        const query = searchQuery.toLowerCase();
        const codeMatch = order.code?.toLowerCase().includes(query);
        const itemMatch = order.itemName?.toLowerCase().includes(query);
        const resellerMatch = order.resellerName?.toLowerCase().includes(query);
        const supplierMatch = order.supplierName?.toLowerCase().includes(query);
        if (!codeMatch && !itemMatch && !resellerMatch && !supplierMatch) {
          return false;
        }
      }

      return true;
    });
  }, [orders, statusFilter, searchQuery]);

  // Derived metrics
  const grossMargin = financials?.netPlatformRevenue ?? 0;
  const gmv = financials?.grossMerchandiseVolume ?? 0;
  const totalStoreExpenses = financials?.totalStoreExpenses ?? 0;
  const netProfit = financials?.netProfit ?? Number((grossMargin - totalStoreExpenses).toFixed(2));
  const marginPercentage = gmv > 0 ? ((grossMargin / gmv) * 100).toFixed(1) : "0.0";
  const netProfitMarginPercent = gmv > 0 ? ((netProfit / gmv) * 100).toFixed(1) : "0.0";
  const clearedBalances = financials?.supplierSettlementLiabilities?.clearedBalance ?? 0;
  const pendingEscrow = financials?.supplierSettlementLiabilities?.pendingEscrow ?? 0;
  const liveInventoryUnits = overview?.activeUnitsCount ?? 0;
  const isReconHealthy = financials?.reconciliation?.isHealthy ?? true;

  // Compute total actionable count
  const totalActionableIssues =
    (actionableCounts.paymentsNeedingReview || 0) +
    (((overview as any)?.storeAlerts?.pendingOrdersCount ?? filterCounts.PENDING) || 0) +
    (((overview as any)?.storeAlerts?.lowStockCount || 0)) +
    (actionableCounts.pendingDeposits || 0) +
    (actionableCounts.pendingPayouts || 0);

  const hasAnyQueueError = Boolean(
    actionableErrors.watchdog ||
    actionableErrors.deposits ||
    actionableErrors.payouts
  );

  return (
    <div className="space-y-6 w-full">
      {/* Top Header & Telemetry Status */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-3 border-b border-border/60">
        <div>
          <h1 className="text-xl sm:text-2xl font-bold tracking-tight text-foreground font-sans">
            Overview
          </h1>
          <p className="text-xs text-muted-foreground mt-0.5">
            Real-time operations, inventory velocity, and financial health.
          </p>
        </div>

        <div className="flex items-center space-x-3 self-start sm:self-auto flex-wrap">
          {/* Truthful Service Health Status Bar */}
          <div className="flex items-center space-x-2 px-3 py-1.5 rounded-xl bg-card border border-border text-xs font-mono text-foreground">
            <span className={`inline-block w-2 h-2 rounded-full ${
