          >
            <div>
              <div className="w-9 h-9 rounded-xl bg-cyan-500/10 border border-cyan-500/30 flex items-center justify-center mb-3 group-hover:scale-105 transition-transform">
                <Tag className="w-4 h-4 text-cyan-400" />
              </div>
              <h3 className="text-sm font-semibold text-foreground mb-1">Supplier offers</h3>
              <p className="text-xs text-muted-foreground leading-relaxed">
                Review and moderate proposed new items and custom pricing from suppliers.
              </p>
            </div>
            <div className="mt-4 pt-3 border-t border-border flex items-center justify-between text-xs font-medium text-cyan-300 group-hover:text-cyan-200">
              <span>Open offers</span>
              <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
            </div>
          </Link>

          <Link
            href="/admin/p2p-watchdog"
            className="p-5 rounded-2xl border border-border bg-card hover:border-foreground/20 transition-all flex flex-col justify-between group shadow-sm"
          >
            <div>
              <div className="w-9 h-9 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center mb-3 group-hover:scale-105 transition-transform">
                <ShieldCheck className="w-4 h-4 text-emerald-400" />
              </div>
              <h3 className="text-sm font-semibold text-foreground mb-1">Payment monitoring</h3>
              <p className="text-xs text-muted-foreground leading-relaxed">
                P2P notification listener, payment matching, and settlement watchdog.
              </p>
            </div>
            <div className="mt-4 pt-3 border-t border-border flex items-center justify-between text-xs font-medium text-emerald-300 group-hover:text-emerald-200">
              <span>Open monitoring</span>
              <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-0.5 transition-transform" />
            </div>
          </Link>
        </div>
      </div>


      {/* Dynamic Transactions & Orders Feed with Interactive Filter Bar */}
      <div className="rounded-2xl border border-border bg-card backdrop-blur-md overflow-hidden space-y-4 p-4 sm:p-6 shadow-xl">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <div className="flex items-center space-x-2">
              <h2 className="text-base font-bold text-foreground font-sans">
                Live Transaction &amp; Order Stream
              </h2>
              <span className="px-2 py-0.5 rounded-full text-[10px] font-mono bg-secondary border border-border text-secondary-foreground">
                {filteredOrders.length} {filteredOrders.length === 1 ? "Record" : "Records"}
              </span>
            </div>
            <p className="text-xs text-muted-foreground mt-0.5">
              Audited fulfillment stream across all reseller channels with wholesale cost and gross platform margins
            </p>
          </div>

          {/* Search Omnibar */}
          <div className="relative w-full sm:w-64">
            <Search className="w-3.5 h-3.5 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search code, item, org..."
              className="w-full pl-8 pr-3 py-1.5 rounded-xl bg-muted/40 border border-border text-xs font-mono text-foreground placeholder:text-muted-foreground focus:outline-none focus:border-border focus:ring-1 focus:ring-border"
            />
          </div>
        </div>

        {/* Filter Bar: All, Pending, Paid, Delivered */}
        <div className="flex items-center overflow-x-auto pb-1 gap-2 border-b border-border">
          {(
            [
              { key: "ALL", label: "All", count: filterCounts.ALL },
              { key: "PENDING", label: "Pending", count: filterCounts.PENDING },
              { key: "PAID", label: "Paid", count: filterCounts.PAID },
              { key: "DELIVERED", label: "Delivered", count: filterCounts.DELIVERED },
            ] as const
          ).map((tab) => {
            const isActive = statusFilter === tab.key;
            return (
              <button
                key={tab.key}
                onClick={() => setStatusFilter(tab.key)}
                className={`flex items-center space-x-2 px-3.5 py-1.5 rounded-xl text-xs font-medium whitespace-nowrap transition-all cursor-pointer ${
                  isActive
                    ? "bg-foreground text-background font-semibold shadow-sm"
                    : "text-muted-foreground hover:text-foreground hover:bg-muted/60"
                }`}
              >
                <span>{tab.label}</span>
                <span
                  className={`text-[10px] font-mono px-1.5 py-0.2 rounded-full ${
                    isActive
                      ? "bg-background/20 text-background"
                      : "bg-muted text-muted-foreground"
                  }`}
                >
                  {tab.count}
                </span>
              </button>
            );
          })}
        </div>

        {/* Data Table Container */}
        {loading ? (
          <div className="p-12 text-center text-xs font-mono text-muted-foreground">
            Loading live transaction ledger...
          </div>
        ) : filteredOrders.length === 0 ? (
          <div className="p-12 text-center rounded-xl border border-dashed border-border text-muted-foreground">
            <Package className="w-8 h-8 mx-auto text-muted-foreground mb-2" />
            <div className="text-xs font-medium text-foreground">No orders found</div>
            <p className="text-[11px] text-muted-foreground mt-1 max-w-sm mx-auto">
              {searchQuery
                ? `No transactions match "${searchQuery}" under ${statusFilter.toLowerCase()} status.`
                : `No transactions currently recorded under "${statusFilter.toLowerCase()}" status.`}
            </p>
            {(statusFilter !== "ALL" || searchQuery) && (
              <button
                onClick={() => {
                  setStatusFilter("ALL");
                  setSearchQuery("");
                }}
                className="mt-3 px-3 py-1 rounded-lg bg-muted hover:bg-muted/80 text-foreground text-xs font-mono cursor-pointer border border-border"
              >
                Reset Filters
              </button>
            )}
          </div>
        ) : (
          <div className="overflow-x-auto -mx-4 sm:mx-0">
            <div className="inline-block min-w-full align-middle">
              <table className="min-w-full text-left font-mono text-xs">
                <thead>
                  <tr className="border-b border-border text-[11px] uppercase tracking-wider text-muted-foreground bg-muted/50">
                    <th scope="col" className="py-2.5 px-3">Order Code</th>
                    <th scope="col" className="py-2.5 px-3">Date</th>
                    <th scope="col" className="py-2.5 px-3">Product / Specification</th>
                    <th scope="col" className="py-2.5 px-3">Channel / Reseller</th>
                    <th scope="col" className="py-2.5 px-3 text-right">Retail (GMV)</th>
                    <th scope="col" className="py-2.5 px-3 text-right">Wholesale</th>
                    <th scope="col" className="py-2.5 px-3 text-right">Gross Margin</th>
                    <th scope="col" className="py-2.5 px-3 text-center">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {filteredOrders.map((order) => {
                    const isFulfilled = order.status === "FULFILLED";
                    const isPaid = order.status === "PAID";
                    const isPending = order.status === "PENDING" || order.status === "RESERVED";
                    const isCancelled = order.status === "CANCELLED" || order.status === "REFUNDED";

                    return (
                      <tr
                        key={order.id}
                        className="hover:bg-muted/40 transition-colors group"
                      >
                        <td className="py-3 px-3 font-bold text-foreground whitespace-nowrap">
                          {order.code}
                        </td>
                        <td className="py-3 px-3 text-muted-foreground text-[11px] whitespace-nowrap">
                          {order.createdAt && !isNaN(new Date(order.createdAt).getTime())
                            ? new Date(order.createdAt).toLocaleDateString(undefined, {
                                month: "short",
                                day: "numeric",
                                hour: "2-digit",
                                minute: "2-digit",
                              })
                            : "Recent"}
                        </td>
                        <td className="py-3 px-3 font-sans text-foreground font-medium whitespace-nowrap max-w-[200px] truncate">
                          {order.itemName}
                        </td>
                        <td className="py-3 px-3 text-muted-foreground whitespace-nowrap">
                          {order.resellerName}
                        </td>
                        <td className="py-3 px-3 text-right text-foreground whitespace-nowrap font-medium">
                          ₱{Number(order?.retailPrice ?? 0).toFixed(2)}
                        </td>
                        <td className="py-3 px-3 text-right text-muted-foreground whitespace-nowrap">
                          ₱{Number(order?.wholesaleCost ?? 0).toFixed(2)}
                        </td>
                        <td className="py-3 px-3 text-right text-emerald-500 dark:text-emerald-400 whitespace-nowrap font-semibold">
                          ₱{Number(order?.grossProfit ?? 0).toFixed(2)}
                        </td>
                        <td className="py-3 px-3 text-center whitespace-nowrap">
                          <span
                            className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-semibold uppercase ${
                              isFulfilled
                                ? "bg-emerald-500/10 text-emerald-500 dark:text-emerald-400 border border-emerald-500/20"
                                : isPaid
                                ? "bg-sky-500/10 text-sky-500 dark:text-sky-400 border border-sky-500/20"
                                : isPending
                                ? "bg-amber-500/10 text-amber-500 dark:text-amber-400 border border-amber-500/20"
                                : "bg-rose-500/10 text-rose-500 dark:text-rose-400 border border-rose-500/20"
                            }`}
                          >
                            {order.status}
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      {/* Store Operational Expenses & Net Profit Management Modal */}
      {showExpenseModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-150">
          <div className="relative w-full max-w-2xl rounded-2xl border border-border bg-card p-6 shadow-2xl space-y-6 max-h-[90vh] overflow-y-auto">
            {/* Modal Header */}
            <div className="flex items-center justify-between border-b border-border pb-4">
              <div className="flex items-center space-x-2.5">
                <div className="w-8 h-8 rounded-xl bg-rose-500/10 border border-rose-500/20 flex items-center justify-center">
                  <Receipt className="w-4 h-4 text-rose-400" />
                </div>
                <div>
                  <h3 className="text-base font-bold text-foreground font-sans">
                    Store Operational Expenses &amp; Net Profit
                  </h3>
                  <p className="text-xs text-muted-foreground">
                    Record operational outflows (hosting, APIs, telecom) to compute true net platform profit
                  </p>
                </div>
              </div>
              <button
                onClick={() => setShowExpenseModal(false)}
                className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted transition-colors cursor-pointer"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Net Platform Profit Equation Summary */}
            <div className="p-4 rounded-xl border border-border bg-muted/40 grid grid-cols-3 gap-3 text-center font-mono text-xs">
              <div>
                <div className="text-[10px] text-muted-foreground uppercase">Gross Margin</div>
                <div className="text-sm font-bold text-foreground">₱{Number(grossMargin ?? 0).toFixed(2)}</div>
              </div>
              <div>
                <div className="text-[10px] text-rose-400 uppercase">- Store Expenses</div>
                <div className="text-sm font-bold text-rose-400">₱{Number(totalStoreExpenses ?? 0).toFixed(2)}</div>
              </div>
              <div>
                <div className="text-[10px] text-emerald-400 uppercase">= Net Profit</div>
                <div className="text-sm font-bold text-emerald-400">₱{Number(netProfit ?? 0).toFixed(2)}</div>
              </div>
            </div>

            {/* Add Expense Form */}
            <form onSubmit={handleCreateExpense} className="space-y-4 p-4 rounded-2xl border border-border bg-muted/30">
              <div className="text-xs font-semibold text-foreground flex items-center space-x-1.5 font-mono">
                <Plus className="w-3.5 h-3.5 text-rose-400" />
                <span>Record New Operational Outflow</span>
              </div>

              {expenseError && (
                <div className="p-3 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-400 text-xs flex items-center space-x-2">
                  <AlertCircle className="w-4 h-4 flex-shrink-0" />
                  <span>{expenseError}</span>
                </div>
              )}

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-[10px] font-mono uppercase text-muted-foreground mb-1">Category</label>
                  <select
                    value={newCategory}
                    onChange={(e) => setNewCategory(e.target.value)}
                    className="w-full px-3 py-1.5 rounded-xl border border-border bg-card text-xs text-foreground focus:outline-none focus:border-ring font-mono"
                  >
                    <option value="Hosting / Domains">Hosting / Domains (Vercel, Cloudflare, etc.)</option>
                    <option value="API Services">API Services (OpenAI, DeepSeek, Upstash)</option>
                    <option value="Product Purchases">Product Purchases / Seed Stock</option>
                    <option value="Telecom">Telecom / SMS Verification</option>
                    <option value="Other">Other Operational Outflow</option>
                  </select>
                </div>

                <div>
                  <label className="block text-[10px] font-mono uppercase text-muted-foreground mb-1">Amount (₱ PHP)</label>
                  <input
                    type="number"
                    step="0.01"
                    required
                    min="0.01"
                    placeholder="e.g. 1500.00"
                    value={newAmount}
                    onChange={(e) => setNewAmount(e.target.value)}
                    className="w-full px-3 py-1.5 rounded-xl border border-border bg-card text-xs text-foreground font-mono focus:outline-none focus:border-ring"
                  />
                </div>

                <div className="sm:col-span-2">
                  <label className="block text-[10px] font-mono uppercase text-muted-foreground mb-1">Description</label>
                  <input
                    type="text"
                    required
                    placeholder="e.g. Vercel Pro Team monthly hosting & serverless compute"
                    value={newDesc}
                    onChange={(e) => setNewDesc(e.target.value)}
                    className="w-full px-3 py-1.5 rounded-xl border border-border bg-card text-xs text-foreground font-mono focus:outline-none focus:border-ring"
                  />
                </div>
              </div>

              <div className="flex justify-end pt-1">
                <button
                  type="submit"
                  disabled={expenseSubmitting || !newDesc.trim() || !newAmount}
                  className="px-4 py-2 rounded-xl bg-foreground hover:opacity-90 text-background text-xs font-semibold uppercase tracking-wider transition-opacity disabled:opacity-50 cursor-pointer shadow-sm"
                >
                  {expenseSubmitting ? "Recording..." : "Save Expense"}
                </button>
              </div>
            </form>

            {/* Expenses List */}
            <div className="space-y-3">
              <div className="flex items-center justify-between text-xs font-mono text-muted-foreground">
                <span>Recorded Store Expenses ({expenses.length})</span>
                <span>Total: ₱{Number(totalStoreExpenses ?? 0).toFixed(2)}</span>
              </div>

              {loadingExpenses ? (
                <div className="p-8 text-center text-xs font-mono text-muted-foreground">Loading expense logs...</div>
              ) : expenses.length === 0 ? (
                <div className="p-8 text-center rounded-xl border border-border text-xs text-muted-foreground font-mono">
                  No store expenses recorded yet.
                </div>
              ) : (
                <div className="divide-y divide-border/50 max-h-56 overflow-y-auto rounded-xl border border-border bg-card font-mono text-xs">
                  {expenses.map((exp: any) => (
                    <div key={exp.id} className="p-3 flex items-center justify-between gap-3">
                      <div>
                        <div className="flex items-center space-x-2">
                          <span className="font-semibold text-foreground">{exp.description}</span>
                          <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-muted border border-border text-muted-foreground">
                            {exp.category}
                          </span>
                        </div>
                        <div className="text-[11px] text-muted-foreground mt-0.5">{exp.date || exp.created_at?.slice(0, 10)}</div>
                      </div>
                      <div className="flex items-center space-x-3">
                        <span className="font-bold text-rose-400">₱{Number(exp?.amount ?? 0).toFixed(2)}</span>
                        <button
                          onClick={() => setExpenseToDelete(exp)}
                          className="p-1 rounded text-muted-foreground hover:text-rose-400 transition-colors cursor-pointer"
                          title="Delete expense"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      <ConfirmDialog
        isOpen={!!expenseToDelete}
        title="Delete expense?"
        description={
          expenseToDelete
            ? `This permanently removes "${expenseToDelete.description}" (₱${Number(expenseToDelete.amount ?? 0).toFixed(2)}) from the store expense records.`
            : undefined
        }
        confirmLabel="Delete"
        destructive
        isLoading={expenseDeleting}
        onConfirm={handleDeleteExpense}
        onCancel={() => setExpenseToDelete(null)}
      />
    </div>
  );
}
